def profile_dtype(model, tokenizer, args):
    from collections import Counter
    import torch
    from makemarket.games import make_game
    from makemarket.market import episode_steps
    from makemarket.players import BayesQuoter

    observations = []
    for game in args.games:
        for index in range(8):
            teacher = BayesQuoter()
            teacher.reset(20000 + index)
            steps = episode_steps(make_game(game), 20000 + index, 'teacher', 'py')
            obs = next(steps)
            for _ in range((0, 1, 3, 5)[index % 4]):
                obs = steps.send(teacher.quote(obs))
            observations.append(obs)
    path = WORK / 'dtype_profile.json'
    record = {**execution(args), 'status': 'running', 'passes': [],
              'training_seeds': [20000, 20007], 'rounds': [0, 1, 3, 5],
              'scope': 'Training-state latency and quote agreement only; no validation or test PnL.',
              'timing_note': 'Ordered before/after probe, two repeats; first repeat includes warm-up. Not an alternating causal hardware benchmark.'}

    def inventory():
        counts = Counter()
        for parameter in model.parameters():
            counts[f'{parameter.device}:{parameter.dtype}'] += parameter.numel()
        return dict(counts)

    def save():
        path.write_text(json.dumps(record, indent=2) + '\n')

    def run(label):
        player = HFQuoter(model, tokenizer, label)
        result = {'mode': label, 'outputs': []}
        record['passes'].append(result)
        for i in range(torch.cuda.device_count()):
            torch.cuda.synchronize(i)
        started = time.monotonic()
        for observation in observations:
            quote, info = player.quote(observation)
            result['outputs'].append({'quote': quote.to_dict() if quote else None, **info})
            result['seconds'] = time.monotonic() - started
            save()
        for i in range(torch.cuda.device_count()):
            torch.cuda.synchronize(i)
        result['seconds'] = time.monotonic() - started
        save()

    try:
        record['parameters_before'] = inventory()
        save()
        run('original_1')
        run('original_2')
        converted = 0
        for parameter in model.parameters():
            if parameter.dtype == torch.bfloat16:
                converted += parameter.numel()
                parameter.data = parameter.data.float()
        changed_compute = 0
        for module in model.modules():
            for name, buffer in module.named_buffers(recurse=False):
                if buffer.dtype == torch.bfloat16:
                    setattr(module, name, buffer.float())
            if getattr(module, 'compute_dtype', None) == torch.bfloat16:
                module.compute_dtype = torch.float32
                changed_compute += 1
        for config in (model.config, getattr(model.config, 'text_config', None)):
            if config is not None:
                config.dtype = torch.float32
        record.update(converted_parameter_elements=converted, changed_compute_modules=changed_compute,
                      parameters_after=inventory())
        save()
        run('fp32_1')
        run('fp32_2')
        quotes = [[row['quote'] for row in p['outputs']] for p in record['passes']]
        record.update(status='completed', all_quotes_equal=all(q == quotes[0] for q in quotes[1:]),
                      all_quotes_valid=all(q is not None for values in quotes for q in values),
                      second_repeat_speedup=record['passes'][1]['seconds']/record['passes'][3]['seconds'])
    except Exception as exc:
        record.update(status='failed', error=f'{type(exc).__name__}: {exc}')
        raise
    finally:
        record['memory_by_gpu'] = [{'device': i, 'peak_allocated_bytes': torch.cuda.max_memory_allocated(i),
                                   'peak_reserved_bytes': torch.cuda.max_memory_reserved(i)}
                                  for i in range(torch.cuda.device_count())]
        save()
